(() => {
'use strict';
const canvas=document.getElementById('game'), ctx=canvas.getContext('2d');
const W=1200,H=760, regions=[
 {name:'Foresta dei Sussurri',short:'FORESTA',icon:'♧',tone:'#476c50',accent:'#a6c58e',weather:'Nebbia antica',effect:'Rigenerazione +10%',boss:'Guardiano delle Radici',foe:'Lupo delle Brume',set:'Selvafoglia'},
 {name:'Paludi Maledette',short:'PALUDE',icon:'♨',tone:'#476b5d',accent:'#8ac5a5',weather:'Miasma',effect:'Veleno +15%',boss:'Idra delle Paludi',foe:'Predatore fangoso',set:'Cacciatore di Torba'},
 {name:'Picchi Innevati',short:'PICCHI',icon:'❄',tone:'#55718a',accent:'#bdd9ef',weather:'Gelo tagliente',effect:'Velocità attacco −12%',boss:'Colosso del Gelo',foe:'Spettro glaciale',set:'Guardia Boreale'},
 {name:'Cittadella Infernale',short:'CITADELLA',icon:'♜',tone:'#78483f',accent:'#ef9870',weather:'Calore estremo',effect:'Danni critici +20%',boss:'Re delle Braci',foe:'Legionario cremisi',set:'Drago Cremisi'},
 {name:'Abisso Cosmico',short:'ABISSO',icon:'✧',tone:'#51416f',accent:'#c3a9ff',weather:'Vuoto astrale',effect:'Danni arcani +18%',boss:'Divoratore di Stelle',foe:'Aberrazione astrale',set:'Eclisse'}
];
const slots=['Arma','Scudo','Elmo','Corazza','Guanti','Stivali'], rarity=['Comune','Non comune','Raro','Epico','Leggendario','Mitico'], rarityColors=['#b8b8ad','#78bd87','#58a9d8','#b479df','#e3ad52','#f07883'];
const baseState={tab:'battle',gold:480,gems:68,dust:12,level:8,xp:64,stage:4,region:0,unlocked:0,bossWins:0,kills:32,atk:146,hp:1280,maxHp:1280,weaponLv:3,expedition:0,expeditionAt:0,starter:false,adfree:false,offlineBoost:1,pity:0,pass:18,claimedDaily:false,inventory:[],gear:[
 {name:'Lama del Crepuscolo',rarity:3,slot:0,power:48,set:'Selvafoglia',level:3},
 {name:'Parabraccio di corteccia',rarity:2,slot:1,power:19,set:'Selvafoglia',level:1},
 {name:'Cappuccio del viandante',rarity:1,slot:2,power:12,set:'Selvafoglia',level:1},
 {name:'Corazza di cuoio',rarity:2,slot:3,power:30,set:'Selvafoglia',level:1},
 {name:'Guanti da esploratore',rarity:1,slot:4,power:11,set:'Selvafoglia',level:1},
 {name:'Stivali del sentiero',rarity:1,slot:5,power:13,set:'Selvafoglia',level:1}
]};
let s; try{s={...baseState,...JSON.parse(localStorage.getItem('ashen-save')||'{}')}}catch{s={...baseState}}
let lastTick=Date.now(), hit=[], modal=null, toastTimer=0, anim=0, enemyHp=100, enemyMax=100, floating=[];
const save=()=>localStorage.setItem('ashen-save',JSON.stringify(s));
function toast(msg){const el=document.getElementById('live-message');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function rounded(x,y,w,h,r=8){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function panel(x,y,w,h,fill='#1b2527',stroke='#344448',r=9){rounded(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}
function text(t,x,y,size=14,color='#dce2db',weight=500,align='left',font='DM Sans'){ctx.font=`${weight} ${size}px '${font}', sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(t,x,y)}
function line(x1,y1,x2,y2,color='#344448',width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function pill(x,y,w,label,color='#d8b46c',bg='#29302a'){panel(x,y,w,23,bg,color,12);text(label,x+w/2,y+12,10,color,700,'center')}
function button(x,y,w,h,label,action,style='gold',sub=''){const styles={gold:['#d4ad69','#30291e','#ead39e'],green:['#547961','#172820','#c3dfc5'],blue:['#4b7081','#18282d','#bfdce5'],dark:['#293638','#182124','#d8dfd8'],red:['#7d4942','#301f1d','#edb4a2']};let [stroke,fill,fg]=styles[style]||styles.gold;panel(x,y,w,h,fill,stroke,7);text(label,x+w/2,y+(sub? h*.39:h*.52),13,fg,700,'center');if(sub)text(sub,x+w/2,y+h*.73,10,'#aab5ad',500,'center');if(action)hit.push({x,y,w,h,action})}
function iconBadge(x,y,r,label,color='#d7b36c'){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle='#192426';ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=1.4;ctx.stroke();text(label,x,y+1,r*1.15,color,700,'center','Marcellus')}
function bar(x,y,w,h,p,color='#c5a15e',bg='#263336'){rounded(x,y,w,h,h/2);ctx.fillStyle=bg;ctx.fill();rounded(x,y,Math.max(h,Math.min(w,w*p)),h,h/2);ctx.fillStyle=color;ctx.fill()}
function bg(){ctx.fillStyle='#11191b';ctx.fillRect(0,0,W,H);const g=ctx.createLinearGradient(0,74,0,760);g.addColorStop(0,'#1b2628');g.addColorStop(1,'#11191b');ctx.fillStyle=g;ctx.fillRect(0,74,W,H-74);}
function header(){
 ctx.fillStyle='#0d1416';ctx.fillRect(0,0,W,74);line(0,73,W,73,'#4e4d3e',1);
 text('ASHEN',30,29,25,'#e1c383',700,'left','Marcellus');text('REALMS',31,52,10,'#81918b',700);line(136,16,136,58,'#354346');text('✦',155,36,17,'#d7b465',600);text('VIANDANTE',178,27,10,'#899891',700);text('Livello '+s.level,178,47,14,'#e8e5d7',700);bar(248,44,125,5,(s.xp/100),'#91a777');
 panel(754,14,132,46,'#172123','#334346',7);text('◉',772,37,17,'#e1bc6c');text(fmt(s.gold),792,37,15,'#f1e2bb',700);panel(896,14,110,46,'#172123','#334346',7);text('✧',914,37,17,'#a998ec');text(fmt(s.gems),934,37,15,'#ded4ff',700);panel(1016,14,92,46,'#172123','#334346',7);text('✥',1034,37,16,'#bc8ad7');text(fmt(s.dust),1054,37,15,'#e6c6ef',700);button(1120,15,62,44,'⚙',()=>openModal('settings'),'dark');
}
function footer(){const tabs=[['hero','✧','EROE'],['battle','⚔','BATTAGLIA'],['world','⌖','MONDO'],['forge','⚒','FORGIA'],['shop','♙','NEGOZIO']];ctx.fillStyle='#0d1416';ctx.fillRect(0,684,W,76);line(0,684,W,684,'#4e4d3e');tabs.forEach((t,i)=>{const x=120+i*240,active=s.tab===t[0];if(active){rounded(x-70,691,140,60,8);ctx.fillStyle='#1d292a';ctx.fill();ctx.fillStyle='#d5ad68';ctx.fillRect(x-70,691,140,2)}text(t[1],x,713,22,active?'#e4c47f':'#70807b',700,'center','Marcellus');text(t[2],x,741,9,active?'#e6d9bb':'#72817c',700,'center');hit.push({x:x-70,y:690,w:140,h:68,action:()=>{s.tab=t[0];save()}})})}
function fmt(n){return Math.floor(n).toLocaleString('it-IT')}
function draw(){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,W,H);hit=[];bg();header();if(modal){renderModal()}else{({battle:drawBattle,hero:drawHero,world:drawWorld,forge:drawForge,shop:drawShop}[s.tab]||drawBattle)();footer()}requestAnimationFrame(draw)}
function title(kicker,title,desc){text(kicker.toUpperCase(),30,101,10,'#9aa895',700);text(title,30,128,25,'#f1e5c7',500,'left','Marcellus');if(desc)text(desc,30,151,12,'#8e9c94',500)}
function artScene(x,y,w,h,region=regions[s.region]){
 ctx.save();rounded(x,y,w,h,10);ctx.clip();const sky=ctx.createLinearGradient(0,y,0,y+h);sky.addColorStop(0,region.tone);sky.addColorStop(.55,'#263b3b');sky.addColorStop(1,'#171f20');ctx.fillStyle=sky;ctx.fillRect(x,y,w,h);
 // moon + distant ridges
 ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(x+w*.78,y+h*.2,25,0,Math.PI*2);ctx.fillStyle=region.accent;ctx.fill();ctx.globalAlpha=1;
 ctx.fillStyle='#273c38';ctx.beginPath();ctx.moveTo(x,y+h*.63);for(let i=0;i<8;i++){ctx.lineTo(x+i*w/7,y+h*(.38+((i%3)*.07)));ctx.lineTo(x+(i+.5)*w/7,y+h*.67)}ctx.lineTo(x+w,y+h*.7);ctx.lineTo(x+w,y+h);ctx.lineTo(x,y+h);ctx.fill();
 ctx.fillStyle='#1b2b29';ctx.beginPath();ctx.moveTo(x,y+h*.76);for(let i=0;i<9;i++){let px=x+i*w/8;ctx.lineTo(px,y+h*(.57+(i%2)*.08));ctx.lineTo(px+w/16,y+h*.78)}ctx.lineTo(x+w,y+h);ctx.lineTo(x,y+h);ctx.fill();
 // branches
 for(let i=0;i<7;i++){let tx=x+((i*137+34)%(w-30))+15,ty=y+h*(.34+((i*7)%27)/100);ctx.strokeStyle='#152421';ctx.lineWidth=5+(i%3)*2;ctx.beginPath();ctx.moveTo(tx,ty+h*.45);ctx.lineTo(tx-10,ty-46);ctx.moveTo(tx-6,ty-24);ctx.lineTo(tx-35,ty-42);ctx.moveTo(tx-1,ty-33);ctx.lineTo(tx+24,ty-53);ctx.stroke();ctx.fillStyle=i%2?'#385746':'#426347';ctx.beginPath();ctx.arc(tx-32,ty-43,17,0,Math.PI*2);ctx.arc(tx+22,ty-54,18,0,Math.PI*2);ctx.fill()}
 // path
 ctx.fillStyle='#6b6045';ctx.beginPath();ctx.moveTo(x+w*.43,y+h);ctx.quadraticCurveTo(x+w*.47,y+h*.77,x+w*.52,y+h*.67);ctx.quadraticCurveTo(x+w*.57,y+h*.77,x+w*.68,y+h);ctx.fill();ctx.globalAlpha=.4;ctx.fillStyle='#c2a676';ctx.fillRect(x+w*.49,y+h*.72,w*.08,2);ctx.globalAlpha=1;
 // hero silhouette
 drawKnight(x+w*.39,y+h*.66,.9);
 // enemy silhouette
 drawEnemy(x+w*.72,y+h*.65,.82,region);
 // atmospheric motes
 for(let i=0;i<18;i++){let xx=x+((i*79+anim*8)%(w-10))+5, yy=y+((i*41+Math.sin(anim+i)*12)%(h*.62));ctx.globalAlpha=.2+(i%3)*.12;ctx.fillStyle=region.accent;ctx.fillRect(xx,yy,2,2)}ctx.globalAlpha=1;
 ctx.restore();panel(x,y,w,h,'#0000','#506054',10)
}
function drawKnight(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#192324';ctx.beginPath();ctx.ellipse(0,3,24,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b9a67c';ctx.fillRect(-10,-52,20,44);ctx.fillStyle='#475b56';ctx.beginPath();ctx.moveTo(-12,-48);ctx.lineTo(-23,-35);ctx.lineTo(-17,-8);ctx.lineTo(0,-4);ctx.lineTo(15,-9);ctx.lineTo(19,-38);ctx.lineTo(11,-50);ctx.fill();ctx.fillStyle='#d5bd85';ctx.beginPath();ctx.arc(0,-57,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#253234';ctx.fillRect(-10,-63,21,6);ctx.strokeStyle='#c4a55e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(16,-43);ctx.lineTo(31,-76);ctx.stroke();ctx.strokeStyle='#dfd5ba';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(28,-70);ctx.lineTo(36,-91);ctx.stroke();ctx.fillStyle='#283638';ctx.fillRect(-13,-12,10,12);ctx.fillRect(4,-11,11,11);ctx.restore()}
function drawEnemy(x,y,scale=1,region=regions[s.region]){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#131b1c';ctx.beginPath();ctx.ellipse(0,1,31,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=region.tone;ctx.beginPath();ctx.moveTo(-25,-8);ctx.lineTo(-21,-37);ctx.lineTo(-6,-56);ctx.lineTo(8,-48);ctx.lineTo(21,-26);ctx.lineTo(27,-7);ctx.closePath();ctx.fill();ctx.fillStyle='#c65e4d';ctx.fillRect(6,-43,5,4);ctx.fillRect(14,-40,4,4);ctx.strokeStyle='#c5a15e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-7,-51);ctx.lineTo(-20,-66);ctx.moveTo(12,-49);ctx.lineTo(22,-63);ctx.stroke();ctx.restore()}

function drawBattle(){const r=regions[s.region];title('Capitolo '+String(s.region+1).padStart(2,'0')+'  /  '+r.short,'La frontiera selvaggia','Il tuo viaggio continua tra antiche rovine e creature dimenticate.');
 panel(26,172,775,493,'#172123','#364649');artScene(39,184,749,309,r);
 // scene labels and battle bars
 panel(55,198,177,49,'#111a1bdc','#ffffff18',6);iconBadge(76,222,12,'✦',r.accent);text('STAGE '+s.stage+' · 10',97,215,10,'#9dac9f',700);text(r.foe,97,232,13,'#f1e4c5',700);
 pill(596,198,174,r.weather+'  ·  '+r.effect,r.accent,'#14201f');
 text('LIVELLO '+s.level,59,519,10,'#95a198',700);text('Viandante',59,539,16,'#e6dcc3',700);bar(59,555,254,9,s.hp/s.maxHp,'#9a695c','#382d2a');text(fmt(s.hp)+' / '+fmt(s.maxHp)+' HP',59,576,10,'#a9b5ad');
 text(r.foe.toUpperCase(),495,519,10,'#95a198',700);text('Creatura errante',495,539,16,'#e6dcc3',700);bar(495,555,254,9,enemyHp/enemyMax,'#bd735a','#382d2a');text(fmt(enemyHp)+' / '+fmt(enemyMax)+' HP',495,576,10,'#a9b5ad');
 line(39,598,788,598,'#344448');text('PROGRESSO STAGE',52,618,10,'#95a198',700);bar(52,636,442,8,Math.min(1,(s.kills%10)/10),'#c4a15f','#2b3839');text((s.kills%10)+'/10',506,640,11,'#e1cfaa',700);
 button(600,609,174,42,'⚔  SFIDA IL BOSS',boss,'red','Ricompensa ×3');
 // right column
 panel(817,172,357,299,'#182224','#364649');text('CRONACHE DI VIAGGIO',840,197,11,'#d7c18e',700);line(839,215,1153,215,'#344448');
 iconBadge(859,245,17,'⌖',r.accent);text('Esplora la regione',888,237,14,'#e5e0d0',700);text('Ogni 10 nemici appare il boss regionale.',888,256,11,'#899891');
 panel(839,278,313,67,'#202c2d','#35474a',7);text('‹',855,311,21,'#c7a86c',600);text('STAGE',884,300,9,'#94a098',700);text(''+s.stage+' / 10',884,322,19,'#ecddba',700);bar(985,298,143,7,Math.min(1,s.stage/10),'#a2bb8a');text('ATK  '+fmt(s.atk),985,322,11,'#bdc9bd',700);text('›',1134,311,21,'#c7a86c',600);
 line(839,363,1153,363,'#344448');text('SPEDIZIONE IDLE',840,386,10,'#d7c18e',700);text(s.expedition?'Esploratori in cammino…':'Invia una squadra a cercare tesori.',840,408,11,'#99a79f');button(840,425,312,34,s.expedition?'⌛  SPEDIZIONE ATTIVA':'➤  INVIA ESPLORATORI',expedition,s.expedition?'dark':'green',s.expedition?'Ricompense tra pochi minuti':'Ricompense offline · 5 min');
 panel(817,483,357,182,'#182224','#364649');text('RICOMPENSE DELLA FRONTIERA',840,508,10,'#d7c18e',700);line(839,525,1153,525,'#344448');iconBadge(860,555,16,'✧','#a998ec');text('Prima esplorazione',888,549,13,'#e3dfd1',700);text('Gemme per ogni nuova regione',888,569,10,'#899891');text('+'+((s.region+1)*15),1130,557,15,'#c3b4f0',700,'right');iconBadge(860,610,16,'⚑','#d7b46b');text('Obiettivo giornaliero',888,604,13,'#e3dfd1',700);text('Sconfiggi 20 creature  ·  '+(s.kills%20)+'/20',888,624,10,'#899891');text('+25',1130,612,14,'#efd38f',700,'right');
}
function boss(){const r=regions[s.region];s.bossWins++;s.kills+=10;s.gold+=90*(1+s.region);s.gems+=4;s.xp+=32;s.pass=Math.min(100,s.pass+5);enemyHp=enemyMax;toast(r.boss+' sconfitto! Bottino ottenuto.');if(s.stage>=10){if(s.region<s.unlocked+0&&s.region<4){s.unlocked=Math.max(s.unlocked,s.region+1);s.region++;s.stage=1;s.gems+=15;toast('Nuova regione sbloccata! +15 gemme')}else if(s.region<4){s.unlocked=Math.max(s.unlocked,s.region+1);s.region++;s.stage=1;s.gems+=15;toast('Nuova regione sbloccata! +15 gemme')}}else{s.stage++;}s.hp=s.maxHp;save()}
function expedition(){if(!s.expedition){s.expedition=1;s.expeditionAt=Date.now();toast('Esploratori partiti! Torna tra 5 minuti.')}else toast('La squadra è ancora in esplorazione.');save()}
function drawHero(){title('IL TUO AVVENTURIERO','Eroe','Una leggenda si forgia un passo alla volta.');
 // left equipment
 panel(26,172,330,493,'#182224','#364649');text('EQUIPAGGIAMENTO',48,198,11,'#d7c18e',700);text('Set '+regions[s.region].set,334,198,10,'#9daf91',600,'right');
 s.gear.forEach((g,i)=>{const yy=221+i*67;panel(43,yy,296,57,'#202b2d',rarityColors[g.rarity],7);iconBadge(70,yy+28,17,['⚔','◈','⌑','▣','✣','⌁'][i],rarityColors[g.rarity]);text(slots[i].toUpperCase(),99,yy+16,9,'#879790',700);text(g.name,99,yy+36,12,'#e8e2d2',700);text('+'+g.power,322,yy+28,12,rarityColors[g.rarity],700,'right');hit.push({x:43,y:yy,w:296,h:57,action:()=>gearInfo(i)})});
 // hero art stage
 panel(368,172,421,316,'#1b2829','#3a4d4b');const r=regions[s.region];artScene(380,184,397,292,r);drawKnight(581,413,1.58);iconBadge(581,237,24,'✦','#d8bc7c');pill(405,201,125,'LIVELLO '+s.level,'#dfc787','#14201f');
 panel(368,500,421,165,'#182224','#364649');text('BONUS SET · '+regions[s.region].set.toUpperCase(),389,525,10,'#d7c18e',700);const setCount=s.gear.filter(g=>g.set===regions[s.region].set).length;text(setCount+' / 6 PEZZI',768,525,10,'#9ca99e',700,'right');bar(389,541,375,6,setCount/4,'#a5bb87');text(setCount>=2?'2 pezzi · +15% ATK':'2 pezzi · +15% ATK  (da attivare)',389,565,11,setCount>=2?'#b8d5a5':'#818e88',600);text(setCount>=4?'4 pezzi · +30% Danno Fuoco':'4 pezzi · +30% Danno Fuoco',389,588,11,setCount>=4?'#b8d5a5':'#818e88',600);line(389,608,765,608,'#344448');text('Abilità sbloccata',389,638,11,'#9fac9c');text('Colpo del viandante',764,638,12,'#e5d7b4',700,'right');
 panel(801,172,373,493,'#182224','#364649');text('STATISTICHE',824,198,11,'#d7c18e',700);line(823,215,1152,215,'#344448');text('POTENZA',824,246,10,'#91a098',700);text(fmt(s.atk),1150,246,20,'#ead4a1',700,'right');text('Vita massima',824,280,12,'#b3bdb3');text(fmt(s.maxHp),1150,280,12,'#e3e1d4',700,'right');text('Critico',824,311,12,'#b3bdb3');text('12%',1150,311,12,'#e3e1d4',700,'right');text('Velocità attacco',824,342,12,'#b3bdb3');text('1.2 / sec',1150,342,12,'#e3e1d4',700,'right');line(823,365,1152,365,'#344448');text('ABILITÀ',824,388,10,'#d7c18e',700);panel(823,405,329,56,'#202c2d','#39494a',7);iconBadge(847,433,16,'⚡','#d8b46c');text('Fendente ardente',873,425,13,'#e5dfcd',700);text('Danno x2 · Ricarica 8 sec',873,444,10,'#899891');line(823,477,1152,477,'#344448');text('INVENTARIO',824,500,10,'#d7c18e',700);text('Oggetti: '+s.inventory.length+' / 40',1152,500,10,'#899891',600,'right');text('Oro',824,532,12,'#b3bdb3');text(fmt(s.gold)+'  ◉',1152,532,12,'#e8cf8e',700,'right');text('Polvere Arcana',824,560,12,'#b3bdb3');text(fmt(s.dust)+'  ✥',1152,560,12,'#d6a8df',700,'right');button(823,590,329,48,'✧  POTENZIA ARMA',upgradeWeapon,'gold','Costo '+fmt(110+s.weaponLv*60)+' oro  ·  livello '+s.weaponLv);
}
function gearInfo(i){const g=s.gear[i];modal={type:'gear',index:i,title:g.name};}
function upgradeWeapon(){const cost=110+s.weaponLv*60;if(s.gold<cost){toast('Oro insufficiente. Continua a combattere!');return}s.gold-=cost;s.weaponLv++;s.atk+=13;s.gear[0].level=s.weaponLv;s.gear[0].power+=13;s.gear[0].name='Lama del Crepuscolo +'+s.weaponLv;toast('Arma potenziata! ATK +13');save()}

function drawWorld(){title('ATLANTE DELLE TERRE SELVAGGE','Il mondo conosciuto','Cinque terre, un solo cammino. Sconfiggi il boss per aprire il passaggio.');
