function purchase(kind){if(kind==='starter'){if(s.starter){toast('Il pacchetto è già stato acquistato.');return}modal={type:'purchase',kind,title:'Pacchetto Principiante',body:'Acquisto simulato · € 2,99\nLama Epica + 300 gemme +20% oro permanente'};return}if(kind==='pass'){modal={type:'purchase',kind,title:'Pass Avventura Premium',body:'Acquisto simulato · € 4,99\nTracciato premium per tutte le 100 tappe'};return}}
function confirmPurchase(){if(!modal)return;if(modal.kind==='starter'){s.starter=true;s.gems+=300;s.inventory.push({name:'Lama del Drago',rarity:3,slot:0,power:82,set:regions[s.region].set,level:1})}else if(modal.kind==='pass'){s.premiumPass=true;s.gems+=30}modal=null;toast('Acquisto simulato confermato. Grazie, viandante!');save()}
function summon(){if(s.gems<80){toast('Servono 80 gemme per evocare.');return}s.gems-=80;s.pity++;const roll=Math.random();let rarityIdx=roll<.02?5:roll<.20?4:roll<.55?3:roll<.85?2:roll<.96?1:0;if(s.pity>=10&&rarityIdx<4){rarityIdx=4;s.pity=0;toast('Pity attivo: Leggendario garantito!')}else if(rarityIdx>=4)s.pity=0;const g={name:['Reliquia delle Brume','Lama del Crepuscolo','Scudo di corteccia','Fendente lunare'][Math.floor(Math.random()*4)],rarity:rarityIdx,slot:Math.floor(Math.random()*6),power:18+rarityIdx*17,set:regions[s.region].set,level:1};s.inventory.push(g);modal={type:'loot',item:g,title:'Evocazione riuscita!'};save()}
function buyConvenience(i){if(i===0){if(s.adfree){toast('Già attivo!');return}modal={type:'purchase',kind:'adfree',title:'Rimuovi pubblicità',body:'Acquisto simulato · € 1,99\nLe pubblicità non sono attive in questo prototipo.'};return}const cost=i===1?60:90;if(s.gems<cost){toast('Gemme insufficienti.');return}s.gems-=cost;if(i===1){toast('Zaino ampliato! Capacità +100.');s.inventoryCapacity=140}else{s.offlineBoost=2;toast('Raccolta offline ×2 attivata!')}save()}
function dailyReward(){if(s.claimedDaily){toast('Ricompensa già riscattata oggi.');return}s.claimedDaily=true;s.gems+=25;s.gold+=200;toast('Ricompensa giornaliera: +25 gemme, +200 oro!');save()}
function claimPass(premium){if(premium&&!s.premiumPass){purchase('pass');return}if(s.pass<1){toast('Avanza nell’avventura per sbloccare ricompense.');return}s.pass=Math.max(0,s.pass-1);s.gems+=premium?25:10;toast('Ricompensa riscattata!');save()}

